+// 下限未満の決着 (B) も、ノード ID として図と表を照合する。
+func TestJudgmentFlowBelowMinimumID(t *testing.T) {
+	inDiagram := strings.Replace(judgmentFlowFixture,
+		"  D1 -- 当たる --> A2\n",
+		"  D1 -- 当たる --> A2\n  D1 -- 下限に満たない --> B1\n", 1)
